scwin.btn_rcv_grp_memb_add_onclick = function(e) {
    try {
        if (dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID") !== "") {
            dts_rcv_grp_memb.insertRow();
            dts_rcv_grp_memb.setCellData(dts_rcv_grp_memb.getFocusedRowIndex(), "CHECK", "T");
            dts_rcv_grp_memb.setCellData(dts_rcv_grp_memb.getFocusedRowIndex(), "RCV_GRP_ID", dts_msg_rcv_grp.getCellData(dts_msg_rcv_grp.getFocusedRowIndex(), "RCV_GRP_ID"));
        } else {
            alert("수신그룹관리를 선택하여 주십시요.");
        }
        // dts_rcv_grp_memb.AddRow();

        // dts_rcv_grp_memb.NameValue(dts_rcv_grp_memb.RowPosition, "CHECK") = "T";

        // dts_rcv_grp_memb.NameValue(dts_rcv_grp_memb.RowPosition, "RCV_GRP_ID") = dts_msg_rcv_grp.NameValue(dts_msg_rcv_grp.RowPosition, "RCV_GRP_ID") ;	
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT42030.btn_rcv_grp_memb_add_onclick" });
    }
};

scwin.btn_rcv_grp_memb_save_onclick = async function(e) {
