///////// 5. 일반/업무 함수 영역 /////////
scwin.deleteRows = function(obj) {
    for (let i = obj.getRowCount() - 1; i >= 0; i--) {
        if (obj.getCellData(i, "CHECK") === "T") obj.removeRow(i);
    }
};

scwin.smsInfo = async function() {

    const options = {
        id: "ULDMGT42035",
        title: "시스템 로그 상세",
        type: "browserPopup",
        width: "830px",
        height: "540px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정,
        callbackFn: "scwin.popupCallback"
    };

    const result = await $c.win.openPopup("/common/ULDMGT42035.gfm", options, data);
    scwin.popupCallback(result);
};

scwin.dataCheck = function() {
    for (let i = 0; i < dts_rcv_grp_memb.getRowCount(); i++) {
        // alert(i+"==>"+dts_rcv_grp_memb.RowStatus(i));
        if (dts_rcv_grp_memb.getRowStatus(i) === 1) {
            const in_val = dts_rcv_grp_memb.getCellData(i, "INTEG_USR_ID");
            const a_len = in_val.length;
            const b_len = in_val.replace(/[^a-z0-9]/gi, '').length;
            if (a_len !== b_len || in_val.length <= 0) {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: dts_rcv_grp_memb.NameString(i, "INTEG_USR_ID") = in_val.replace(/[^a-z0-9]/gi, '');*/
                X = in_val.replace(/[^a-z0-9]/gi, '');
                alert("영어, 숫자만 입력 가능합니다.");
                return false;
            }
        }
    }
    return true;
};

scwin.gform_onload = function() {
    //	alert('gform.onload');

